  "Rotates all characters to the bind pose; resets pose history, part visibilities, hidden characters, control size and camera framing. The pose library is preserved.": "Dreht alle Charaktere in die Bind-Pose; setzt Posen-Protokoll, Teil-Sichtbarkeiten, ausgeblendete Charaktere, Steuerungsgröße und Kamera-Rahmung zurück. Die Posen-Bibliothek bleibt erhalten.",
