  "The app saves everything itself; you continue where you left off when you reopen.": "Die App speichert alles selbst; beim erneuten Öffnen machst du dort weiter, wo du aufgehört hast.",
  "The backup folder can only open in the desktop app.": "Der Sicherungsordner lässt sich nur in der Desktop-App öffnen.",
  "The character is gone — press F (or ⌖ Focus) and it comes back to the middle.": "Der Charakter ist weg — drücke F (oder ⌖ Fokus), dann kommt er in die Mitte zurück.",
  "The component design of the program — how buttons, bars and windows look. Colors still come from the theme; the two layers are independent.": "Das Komponentendesign des Programms – wie Schaltflächen, Leisten und Fenster aussehen. Die Farben kommen weiterhin vom Theme; beide Ebenen sind unabhängig.",
  "The current TailRef interface — default, always available.": "Die aktuelle TailRef-Oberfläche – Standard, immer verfügbar.",
  "The date this desktop app was packaged. Empty means a development run.": "Das Datum, an dem diese Desktop-App gepackt wurde. Leer bedeutet einen Entwicklungslauf.",
  "The eye icon hides a part, the frame shows only that part. Background settings are in the left strip.": "Das Augensymbol versteckt ein Teil, der Rahmen zeigt nur dieses Teil. Hintergrund-Einstellungen sind im linken Streifen.",
  "The gizmo's own X/Y/Z axes": "Die eigenen X/Y/Z-Achsen des Gizmos",
  "The graphics adapter the program renders with, as reported by your GPU driver.": "Der Grafikadapter, mit dem das Programm rendert, gemeldet vom GPU-Treiber.",
  "The key guide shows every shortcut with its action; open it any time.": "Die Tastaturhilfe zeigt jedes Kürzel mit seiner Aktion; jederzeit öffnen.",
  "The panel closed — click 3D at the top to open it again.": "Das Panel ist zu — klicke oben auf 3D, um es wieder zu öffnen.",
  "The path was copied to the clipboard; paste it into the address bar to open.": "Der Pfad wurde in die Zwischenablage kopiert; füge ihn zum Öffnen in die Adressleiste ein.",
  "The pose is a mess — press ⟲ Reset in the POSE card.": "Die Pose ist durcheinander — in der POSE-Karte ⟲ Zurücksetzen drücken.",
  "The seven theme colors: background, panel surface, borders, text, secondary text, accent and the text color drawn on top of the accent.": "Die sieben Theme-Farben: Hintergrund, Panel-Oberfläche, Rahmen, Text, Sekundärtext, Akzent und die Textfarbe auf dem Akzent.",
