  "The component design of the program — how buttons, bars and windows look. Colors still come from the theme; the two layers are independent.": "El diseño de componentes del programa: cómo se ven los botones, las barras y las ventanas. Los colores siguen viniendo del tema; las dos capas son independientes.",
