  "The date this desktop app was packaged. Empty means a development run.": "La fecha en que se empaquetó esta aplicación de escritorio. Vacío significa una ejecución de desarrollo.",
  "The eye icon hides a part, the frame shows only that part. Background settings are in the left strip.": "El icono de ojo oculta una parte, el marco muestra solo esa parte. Los ajustes de fondo están en la franja izquierda.",
  "The gizmo's own X/Y/Z axes": "Los ejes X/Y/Z propios del manipulador",
  "The graphics adapter the program renders with, as reported by your GPU driver.": "El adaptador gráfico con el que renderiza el programa, según informa tu controlador de GPU.",
  "The key guide shows every shortcut with its action; open it any time.": "La guía de teclas muestra cada atajo con su acción; ábrela en cualquier momento.",
  "The panel closed — click 3D at the top to open it again.": "El panel se cerró — haz clic en 3D arriba para volver a abrirlo.",
  "The path was copied to the clipboard; paste it into the address bar to open.": "La ruta se copió al portapapeles; pégala en la barra de direcciones para abrirla.",
  "The pose is a mess — press ⟲ Reset in the POSE card.": "La pose es un desastre — pulsa ⟲ Restablecer en la tarjeta POSE.",
  "The seven theme colors: background, panel surface, borders, text, secondary text, accent and the text color drawn on top of the accent.": "Los siete colores del tema: fondo, superficie del panel, bordes, texto, texto secundario, acento y el color del texto dibujado sobre el acento.",
  "The slider button in the toolbox: size, opacity, hardness, spacing, smoothing and": "El botón deslizador de la caja de herramientas: tamaño, opacidad, dureza, espaciado, suavizado y",
