  "The character is gone — press F (or ⌖ Focus) and it comes back to the middle.": "Le personnage a disparu — appuyez sur F (ou ⌖ Focus), il revient au centre.",
  "The component design of the program — how buttons, bars and windows look. Colors still come from the theme; the two layers are independent.": "Le design des composants du programme — l'apparence des boutons, barres et fenêtres. Les couleurs viennent toujours du thème ; les deux couches sont indépendantes.",
  "The current TailRef interface — default, always available.": "L'interface TailRef actuelle — par défaut, toujours disponible.",
