  "The eye icon hides a part, the frame shows only that part. Background settings are in the left strip.": "L'icône œil masque une partie, le cadre ne montre que cette partie. Les réglages d'arrière-plan sont dans la bande de gauche.",
  "The gizmo's own X/Y/Z axes": "Les axes X/Y/Z propres au gimbal",
