  "Hold and drag the title → the window moves (desktop). If untouched for 1 minute it slowly fades out; it comes back on hover": "タイトルを持って引くと → ウィンドウが動きます（デスクトップ）。1 分間さわらないとゆっくり消えます。マウスを乗せると戻ります",
