  "The component design of the program — how buttons, bars and windows look. Colors still come from the theme; the two layers are independent.": "プログラムのコンポーネントデザイン — ボタン、バー、ウィンドウの見た目。色は引き続きテーマから取得され、2つのレイヤーは独立しています。",
