  "Rotates all 3D characters to the bind pose; resets pose history, size multipliers (dev/peri) and character/part visibility. The camera is re-framed. Does NOT touch the pose library or the 2D board.": "3D 캐릭터 전체를 바인드 포즈로 돌립니다. 포즈 기록, 크기 배율(거인/요정), 캐릭터/파트 표시를 초기화합니다. 카메라는 다시 조립됩니다. 포즈 라이브러리와 2D 보드에는 손대지 않습니다.",
  "Rotates all characters to the bind pose; resets pose history, part visibilities, hidden characters, control size and camera framing. The pose library is preserved.": "모든 캐릭터를 바인드 포즈로 돌립니다. 포즈 기록, 파트 표시, 숨긴 캐릭터, 조작 크기, 카메라 프레이밍을 초기화합니다. 포즈 라이브러리는 보존됩니다.",
