  "Save your preferences (themes, language, panels, shortcuts and more) to a tailref-preferences.json file. Board content is never included.": "설정(테마, 언어, 패널, 단축키 등)을 tailref-preferences.json 파일로 저장합니다. 보드 내용은 절대 포함되지 않습니다.",
  "Save your work before TailRef restarts to install the update?": "업데이트를 설치하려면 TailRef가 재시작됩니다. 작업을 저장할까요?",
  "Save, reset and saved poses live in the left strip. To add to the board use ◉ Capture in Tools (Ctrl+Shift+S).": "저장, 초기화, 저장된 포즈는 왼쪽 스트립에 있습니다. 보드에 추가하려면 TOOLS 의 ◉ 캡처 (Ctrl+Shift+S) 를 사용하세요.",
