  "Sets the pose base: T-pose opens arms fully horizontal, A-pose lowers them 45°. Saved poses are applied on top of this base.": "포즈 기준을 정합니다: T 포즈는 팔을 완전히 수평으로 벌리고, A 포즈는 45° 내립니다. 저장된 포즈는 이 기준 위에 적용됩니다.",
