  "Shadow and detail density in the 3D Pose section. In Auto the program watches the frame rate; it throttles when it lags and raises when it relaxes. A manual choice is left alone.": "3D 포즈 섹션의 그림자와 디테일 밀도. 자동이면 프로그램이 프레임률을 감시합니다. 느려지면 낮추고 여유가 생기면 올립니다. 수동 선택은 그대로 존중됩니다.",
