  "The app saves everything itself; you continue where you left off when you reopen.": "앱이 스스로 모든 것을 저장합니다. 다시 열면 중단한 곳에서 이어집니다.",
  "The backup folder can only open in the desktop app.": "백업 폴더는 데스크톱 앱에서만 열 수 있습니다.",
  "The character is gone — press F (or ⌖ Focus) and it comes back to the middle.": "캐릭터가 사라졌어요 — F(또는 ⌖ 포커스)를 누르면 가운데로 돌아옵니다.",
  "The component design of the program — how buttons, bars and windows look. Colors still come from the theme; the two layers are independent.": "프로그램의 구성 요소 디자인 — 버튼, 바, 창의 모양입니다. 색상은 여전히 테마에서 가져오며 두 레이어는 독립적입니다.",
  "The current TailRef interface — default, always available.": "현재 TailRef 인터페이스 — 기본이며 항상 사용할 수 있습니다.",
  "The date this desktop app was packaged. Empty means a development run.": "이 데스크톱 앱이 패키징된 날짜. 비어 있으면 개발 실행입니다.",
  "The eye icon hides a part, the frame shows only that part. Background settings are in the left strip.": "눈 아이콘은 파트를 숨기고, 테두리는 그 파트만 표시합니다. 배경 설정은 왼쪽 스트립에 있습니다.",
  "The gizmo's own X/Y/Z axes": "기즈모 자체의 X/Y/Z 축",
  "The graphics adapter the program renders with, as reported by your GPU driver.": "프로그램이 렌더링에 사용하는 그래픽 어댑터. GPU 드라이버가 보고한 값입니다.",
  "The key guide shows every shortcut with its action; open it any time.": "키 가이드는 모든 단축키와 그 동작을 보여 줍니다. 언제든 열 수 있습니다.",
  "The panel closed — click 3D at the top to open it again.": "패널이 닫혔어요 — 위쪽의 3D를 클릭하면 다시 열립니다.",
  "The path was copied to the clipboard; paste it into the address bar to open.": "경로를 클립보드에 복사했습니다. 주소 표시줄에 붙여 넣어 여세요.",
