  "The seven theme colors: background, panel surface, borders, text, secondary text, accent and the text color drawn on top of the accent.": "테마의 일곱 가지 색상: 배경, 패널 표면, 테두리, 텍스트, 보조 텍스트, 강조 색, 그리고 강조 색 위에 그려지는 텍스트 색.",
  "The slider button in the toolbox: size, opacity, hardness, spacing, smoothing and": "도구 상자의 슬라이더 버튼: 크기, 불투명도, 굳기, 간격, 부드럽기,",
