  "Idle fade": "Desvanecer em repouso",
  "If it gets messy, reset; save when you like it": "Se bagunçar, redefina; salve quando gostar",
  "If rigs or poses get corrupted, one click restores factory state. The pose library is not deleted.": "Se rigs ou poses se corromperem, um clique restaura o estado de fábrica. A biblioteca de poses não é apagada.",
  "If something gets stuck": "Se algo travar",
  "If the view drifts, in the TOOLS card": "Se a vista derivar, no cartão FERRAMENTAS",
  "If this is your first time in 3D you are in the right place. Five cards guide your work in the left strip:": "Se é sua primeira vez no 3D, você está no lugar certo. Cinco cartões guiam seu trabalho na faixa à esquerda:",
