  "Mouse": "Мышь",
  "Mouse buttons for orbiting, panning and zooming in 3D. Industry standard: Alt + left orbits, Alt + middle pans, Alt + right zooms. Blender: middle orbits, Shift + middle pans, Ctrl + middle zooms. The wheel always zooms.": "Кнопки мыши для вращения, панорамирования и масштабирования в 3D. Отраслевой стандарт: Alt + левая вращает, Alt + средняя панорамирует, Alt + правая масштабирует. Blender: средняя вращает, Shift + средняя панорамирует, Ctrl + средняя масштабирует. Колесо всегда масштабирует.",
