  "Rotates all characters to the bind pose; resets pose history, part visibilities, hidden characters, control size and camera framing. The pose library is preserved.": "Поворачивает всех персонажей в базовую позу; сбрасывает историю поз, видимость частей, скрытых персонажей, размер управления и кадрирование камеры. Библиотека поз сохраняется.",
