  "The eye icon hides a part, the frame shows only that part. Background settings are in the left strip.": "Иконка глаза прячет часть, рамка показывает только её. Настройки фона — в левой полосе.",
  "The gizmo's own X/Y/Z axes": "Собственные оси X/Y/Z гизмо",
