  "The panel closed — click 3D at the top to open it again.": "Панель закрылась — нажмите 3D вверху, чтобы открыть снова.",
  "The path was copied to the clipboard; paste it into the address bar to open.": "Путь скопирован в буфер обмена; вставьте его в адресную строку, чтобы открыть.",
  "The pose is a mess — press ⟲ Reset in the POSE card.": "Поза развалилась — нажмите ⟲ Сброс в карточке POSE.",
  "The seven theme colors: background, panel surface, borders, text, secondary text, accent and the text color drawn on top of the accent.": "Семь цветов темы: фон, поверхность панели, рамки, текст, вторичный текст, акцент и цвет текста поверх акцента.",
  "The slider button in the toolbox: size, opacity, hardness, spacing, smoothing and": "Кнопка-ползунок набора инструментов: размер, прозрачность, жёсткость, шаг, сглаживание и",
