  "Icon · 256px": "Simge · 256px",
  "Idle fade": "Boşta soldurma",
  "If it gets messy, reset; save when you like it": "Karışırsa sıfırla, beğenince kaydet",
  "If rigs or poses get corrupted, one click restores factory state. The pose library is not deleted.": "Rigler ya da possalar bozulursa tek dokunuşla fabrika durumu. Poz kütüphanesi silinmez.",
  "If something gets stuck": "Bir şey takılırsa",
  "If the view drifts, in the TOOLS card": "Görüntü kayarsa ARAÇLAR kartındaki",
  "If this is your first time in 3D you are in the right place. Five cards guide your work in the left strip:": "İlk kez 3D kullanacaksan doğru yerdesin. Soldaki şeritte işinin geçeceği beş kart var:",
