  "Import .abr": ".abr içe aktar",
  "Import .json": ".json içe aktar",
  "Import a declarative interface package (.tailref-ui.json). No code is executed; unsafe packages are rejected.": "Dekleratif arayüz paketi içe aktar (.tailref-ui.json). Kod çalıştırılmaz; güvensiz paketler reddedilir.",
  "Import poses from a JSON file": "JSON dosyasından poz içe aktar",
  "Import preferences": "Tercihleri içe aktar",
  "Important": "Önemli",
  "In the POSE card, turn Controls on. A small circle appears on each joint: shoulder, elbow, knee and so on. You pose the character by grabbing these circles.": "POZ kartında Kontroller'i aç. Omuz, dirsek, diz gibi her eklemde küçük bir halka belirir. Karaktere bu halkalardan tutarak poz verirsin.",
  "In the SAVE card, press ○ Save. You can give it a name first. Click a saved pose later and the character returns to exactly that pose.": "KAYDET kartında ○ Kaydet'e bas. İstersen önce bir isim ver. Kaydettiğin poza sonra tıkladığında karakter tam o poza döner.",
  "In the TOOLS card, press ◉ Capture (Ctrl+Shift+S also works). Choose a size, check it with Preview render, then press Add to board. The pose becomes an image on your board, ready to draw over.": "ARAÇLAR kartında ◉ Yakala'ya bas (Ctrl+Shift+S de çalışır). Bir boyut seç, Önizle ile kontrol et, sonra Tahtaya ekle düğmesine bas. Poz, panonda üzerine çizebileceğin bir görüntü olur.",
  "In the image editor, Ctrl + wheel zoom keeps the point under the cursor in place. Off zooms around the canvas centre.": "Görüntü editöründe Ctrl + tekerlek yakınlaştırması imlecin altındaki noktayı sabit tutar. Kapalıyken tuval merkezi çevresinde yakınlaştırır.",
  "Include drawing layer": "Çizim katmanını dahil et",
  "Include guides": "Kılavuzları dahil et",
