  "The character is gone — press F (or ⌖ Focus) and it comes back to the middle.": "Karakter kayboldu — F'ye (veya ⌖ Odak) bas, ortaya gelir.",
  "The component design of the program — how buttons, bars and windows look. Colors still come from the theme; the two layers are independent.": "Programın bileşen tasarımı — düğmeler, çubuklar ve pencereler nasıl görünür. Renkler temadan gelir; iki katman bağımsızdır.",
