  "How many actions you can undo (5–200), like Photoshop's History States. Empty keeps the program default (editor 30, board 60); a memory budget always protects big canvases.": "可撤销的操作数 (5–200)，类似 Photoshop 的历史记录状态。留空则保持程序默认（编辑器 30，画板 60）；内存预算始终保护大画布。",
  "How many automatic backups are kept in the backup folder; older ones are deleted. Good and emergency backups are not affected.": "备份文件夹中保留多少个自动备份；较旧的会被删除。良好副本和紧急备份不受影响。",
  "How often the app writes a backup while you work.": "工作时应用每隔多久写一次备份。",
  "How opaque panels are. Lower values let the background image show through panel surfaces.": "面板的不透明度。数值越低，背景图片越能透过面板表面显示。",
  "How raw tablet pressure is mapped onto the stroke. Linear keeps full tablet sensitivity; Soft fills in light strokes sooner; Hard requires more pressure for full size.": "平板的原始压力如何映射到笔画。线性保留平板的全部灵敏度；柔和让轻压笔画更快饱和；坚硬需要更大压力才能达到最大尺寸。",
